function initFeaturedPostsSwiper(e){if("undefined"==typeof Swiper)return;const t=e.closest(".featured-posts-section"),r=e.querySelectorAll(".swiper-slide").length;new Swiper(e,{slidesPerView:"auto",spaceBetween:24,loop:r>4,speed:500,grabCursor:!0,keyboard:{enabled:!0},navigation:t?{nextEl:t.querySelector(".featured-posts-section__nav--next"),prevEl:t.querySelector(".featured-posts-section__nav--prev")}:void 0})}document.addEventListener("DOMContentLoaded",()=>{document.querySelectorAll(".featured-posts-section__swiper").forEach(initFeaturedPostsSwiper)});